#!/usr/bin/env bash
# (1439) 合流：合わせた木の絞った試験（m1432/narrow.sh の写し・束を ㉘ の走査の番人と、rx・sd・ha が変えた名を Tests/ で grep して当たったクラスへ替えた・FullLength を除く）。
#   bash narrow.sh <作業フォルダ（D:/…）> <名>
WK=${1:?作業フォルダ}; N=${2:?名}; mkdir -p $WK/tmp
export TEMP=$WK/tmp TMP=$WK/tmp
cd "$(dirname "$0")/../../.."; A=$WK/art
dotnet build PriceOfBread.Tests -c Release --artifacts-path $A -v q -nologo > $WK/build_$N.txt 2>&1 || { echo BUILDFAIL; exit 1; }
F="FullyQualifiedName~AiFirstWaveTests|FullyQualifiedName~ConservationTests|FullyQualifiedName~CreditTests|FullyQualifiedName~DerivedValueRatchetTests|FullyQualifiedName~DestFoodSymmetryTests|FullyQualifiedName~DiplomacyPendingTests|FullyQualifiedName~DiscontentReaderTests|FullyQualifiedName~DiscontentSplitTests|FullyQualifiedName~DormantIdentityTests|FullyQualifiedName~FactionFloorRegionTests|FullyQualifiedName~FiscalTests|FullyQualifiedName~HungerFlightTests|FullyQualifiedName~IdeaNeedBoardTests|FullyQualifiedName~IndustrializationReaderTests|FullyQualifiedName~InstrumentHookClosureTests|FullyQualifiedName~LaborMarketFormTests|FullyQualifiedName~LawPreferenceDirectionTests|FullyQualifiedName~LawstepInstrumentTests|FullyQualifiedName~LordStakeD1bD2Tests|FullyQualifiedName~MultiNationTests|FullyQualifiedName~NationalismUnificationTests|FullyQualifiedName~PartyTests|FullyQualifiedName~PolicyPoliticsTests|FullyQualifiedName~PoliticsUnificationC148poTests|FullyQualifiedName~PrdsShadowTests|FullyQualifiedName~RandomOnlyClimateEpidemicTests|FullyQualifiedName~ReceiveCapRoomTests|FullyQualifiedName~ReligionTensionRemovalTests|FullyQualifiedName~RevoltIgnitionTests|FullyQualifiedName~Rs3LordReverseGainTests|FullyQualifiedName~SatReadersToDiscontentTests|FullyQualifiedName~SaveRoundTripTests|FullyQualifiedName~SbBargainTests|FullyQualifiedName~TechLevelRemovalTests|FullyQualifiedName~TensionPoliticsTests|FullyQualifiedName~TensionTableOrderTests|FullyQualifiedName~TerritoryTests|FullyQualifiedName~UnderconsumptionTests|FullyQualifiedName~UnitTypeTests|FullyQualifiedName~WarExitFromCapacityTests|FullyQualifiedName~WarThemeTests|FullyQualifiedName~WriterRatchetTests|FullyQualifiedName~ValueCountRatchetTests|FullyQualifiedName~InstrumentsTests|FullyQualifiedName~InstrumentColumnTests|FullyQualifiedName~MilitaryTests|FullyQualifiedName~ProtectorTests|FullyQualifiedName~RouteTensionTests"
dotnet test PriceOfBread.Tests -c Release --artifacts-path $A --no-build --filter "($F)&Category!=FullLength" --logger "trx;LogFileName=$N.trx" --results-directory $WK/trx > $WK/t_$N.txt 2>&1
RC=$?; grep -E "合計|失敗 |Failed " $WK/t_$N.txt | head -30; exit $RC
